}.active-neon-card { background: linear-gradient(-45deg, rgb(0, 122, 255), rgb(0, 91, 193), rgb(0, 162, 255), rgb(0, 91, 193)) 0% 0% / 400% 400%; animation: 15s ease 0s infinite normal none running dune-wind; border: 1px solid rgba(255, 255, 255, 0.1); box-shadow: rgba(0, 122, 255, 0.4) 0px 8px 24px, rgba(255, 255, 255, 0.4) 0px 1px 1px inset; color: white; }.bp-dialog { background: rgb(19, 19, 21); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 12px; box-shadow: rgba(0, 0, 0, 0.6) 0px 20px 40px; padding: 24px; width: 90%; max-width: 300px; display: flex; flex-direction: column; gap: 12px; transform: scale(0.95); animation: 0.2s cubic-bezier(0.2, 0.8, 0.2, 1) 0s 1 normal forwards running bp-pop-in; }@keyframes bp-pop-in { 
  100% { transform: scale(1); }
}.bp-dialog-title { font-size: 16px; font-weight: 600; color: rgb(173, 198, 255); margin: 0px; display: flex; align-items: center; gap: 8px; }.bp-dialog-desc { font-size: 14px; color: rgb(193, 198, 215); margin: 0px; line-height: 1.5; }.bp-dialog-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 12px; }.bp-dialog-btn { padding: 8px 16px; border-radius: 6px; font-size: 13px; font-weight: 500; cursor: pointer; transition: 0.2s; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; }.bp-dialog-btn-cancel { background: rgba(255, 255, 255, 0.1); color: rgb(193, 198, 215); }.bp-dialog-btn-cancel:hover { background: rgba(255, 255, 255, 0.15); color: rgb(228, 226, 228); }.bp-dialog-btn-stop { background: rgba(147, 0, 10, 0.3); color: rgb(255, 180, 171); }.bp-dialog-btn-stop:hover { background: rgba(147, 0, 10, 0.4); }
